import * as https from 'node:https';
import * as zlib from 'node:zlib';
import process from 'node:process';
const CERT = `-----BEGIN CERTIFICATE-----
MIIBnDCCAUGgAwIBAgIUDvJfKn/S5YKxpIJoI/kK/zrdaucwCgYIKoZIzj0EAwIw
FDESMBAGA1UEAwwJbG9jYWxob3N0MCAXDTI2MTExNzE5NDY0OVoYDzIxMjYxMDI0
MTk0NjQ5WjAUMRIwEAYDVQQDDAlsb2NhbGhvc3QwWTATBgcqhkjOPQIBBggqhkjO
