aQwNz1bICAeSFKMiihWoL6didBqbSnwto28wbTAdBgNVHQ4EFgQUi29U2ZbCayvF
ZQQR5KlS0HiRJxUwHwYDVR0jBBgwFoAUi29U2ZbCayvFZQQR5KlS0HiRJxUwDwYD
VR0TAQH/BAUwAwEB/zAaBgNVHREEEzARgglsb2NhbGhvc3SHBH8AAAEwCgYIKoZI
zj0EAwIDSQAwRgIhAOTOjtipVAiB8/DQgg8E4oL/Kw97Pyn5P1RaRZkG9PuEAiEA
sZUZBHoaCHTsuAXJe6+C6zIp13sJ/mUfH6fA/6byCxU=
-----END CERTIFICATE-----
`;
const KEY = `-----BEGIN PRIVATE KEY-----
MIGHAgEAMBMGByqGSM49AgEGCCqGSM49AwEHBG0wawIBAQQgWnPSZZHIbdcItD25
AEtzp6c402gyrrnFFvWPtgiDaJmhRANCAASmZc+W42jDodYVFMNG+NphQob6jgC8
dsGU1RprH4GpiQMFNxFgUI9QaQwNz1bICAeSFKMiihWoL6didBqbSnwt
-----END PRIVATE KEY-----
`;
function main(): void {
  const payload = Buffer.from('loopback https payload '.repeat(20));
  const packed = zlib.brotliCompressSync(payload);
  const srv = https.createServer({ key: KEY, cert: CERT }, (req: any, res: any) => {
    res.writeHead(200, { 'content-type': 'text/plain', 'content-encoding': 'br' });
    res.end(packed);
  });
  srv.listen(0, '127.0.0.1', (): void => {
    const port = (srv.address() as any).port;
    https.get({ host: '127.0.0.1', port, path: '/', ca: CERT }, (res: any): void => {
      const chunks: Buffer[] = [];
      res.on('data', (chunk: Buffer): void => { chunks.push(chunk); });
      res.on('end', (): void => {
        const text = zlib.brotliDecompressSync(Buffer.concat(chunks)).toString('utf8');
        console.log(res.statusCode, text.length, text.slice(0, 23));
        srv.close();
      });
    });
  });
}
